SELECT *
FROM stock_stat s
WHERE s.market_type IN

    #{marketType}


    AND s.sector IN

        #{sector}



    AND s.market_cap BETWEEN #{filters.marketCap.min} AND #{filters.marketCap.max}


    AND s.per BETWEEN #{filters.per.min} AND #{filters.per.max}


    AND s.eps BETWEEN #{filters.eps.min} AND #{filters.eps.max}


    AND s.bps BETWEEN #{filters.bps.min} AND #{filters.bps.max}


    AND s.pbr BETWEEN #{filters.pbr.min} AND #{filters.pbr.max}


    AND s.dividend_yield BETWEEN #{filters.dividendYield.min} AND #{filters.dividendYield.max}


    AND s.foreigner_ratio BETWEEN #{filters.foreignerRatio.min} AND #{filters.foreignerRatio.max}


    AND s.sps BETWEEN #{filters.sps.min} AND #{filters.sps.max}


    AND s.sale_account BETWEEN #{filters.saleAccount.min} AND #{filters.saleAccount.max}


