    AND s.lblt_rate BETWEEN #{filters.lbltRate.min} AND #{filters.lbltRate.max}


    AND s.ntin_inrt BETWEEN #{filters.ntinInrt.min} AND #{filters.ntinInrt.max}


    AND s.bsop_prfi_inrt BETWEEN #{filters.bsopPrfiInrt.min} AND #{filters.bsopPrfiInrt.max}


    AND s.grs BETWEEN #{filters.grs.min} AND #{filters.grs.max}


    AND s.roe_val BETWEEN #{filters.roeVal.min} AND #{filters.roeVal.max}


    AND s.bsop_prti BETWEEN #{filters.bsopPrti.min} AND #{filters.bsopPrti.max}


    AND s.thtr_ntin BETWEEN #{filters.thtrNtin.min} AND #{filters.thtrNtin.max}

ORDER BY s.company_name DESC  
LIMIT #{limit} OFFSET #{offset}

